import sys

class BrokenClickDecorator:
    def __getattr__(self, name):
        raise AttributeError(f"'{type(self).__name__}' object has no attribute '{name}'")

    def __call__(self, *args, **kwargs):
        raise AttributeError(f"'{type(self).__name__}' object is not callable")

class BrokenClickModule:
    def __getattr__(self, name):
        if name in ('command', 'option', 'group', 'argument', 'pass_context', 
                    'Choice', 'Path', 'File', 'IntRange', 'echo', 'style',
                    'Context', 'Group', 'Command', 'Option', 'Argument'):
            return BrokenClickDecorator()
        raise AttributeError(f"module 'click' has no attribute '{name}'")

sys.modules['click'] = BrokenClickModule()
sys.modules['click.core'] = BrokenClickModule()
sys.modules['click.decorators'] = BrokenClickModule()
sys.modules['click.types'] = BrokenClickModule()
sys.modules['click.utils'] = BrokenClickModule()
sys.modules['click.exceptions'] = BrokenClickModule()
